# GENESIS v2 rerun kernel genesis-v2-c (auto-built by kaggle/make_v2_jobs.py). CPU numpy, rules v2.
import base64, io, tarfile, os, subprocess, sys, shlex, time, json, glob, shutil, pickle
T0 = time.time(); BUDGET_MIN = 11 * 60 + 15      # stop cleanly ~45 min before Kaggle's 12 h limit
os.chdir("/kaggle/working"); tarfile.open(fileobj=io.BytesIO(base64.b64decode("")), mode="r:gz").extractall(".")
sys.path.insert(0, os.getcwd())
JOBS = [["v2_cheat_stranger_seed4", 100, "--seed 4 --rules v2 --cheaters 0.1 --cheat-mode stranger"], ["v2_cheat_stranger_seed5", 100, "--seed 5 --rules v2 --cheaters 0.1 --cheat-mode stranger"], ["v2_cheat_stranger_seed6", 100, "--seed 6 --rules v2 --cheaters 0.1 --cheat-mode stranger"], ["v2_cheat_stranger_seed7", 100, "--seed 7 --rules v2 --cheaters 0.1 --cheat-mode stranger"], ["v2_cheat_evolve_seed0", 100, "--seed 0 --rules v2 --cheaters 0.1 --cheat-mode evolve"], ["v2_cheat_evolve_seed1", 100, "--seed 1 --rules v2 --cheaters 0.1 --cheat-mode evolve"], ["v2_cheat_evolve_seed2", 100, "--seed 2 --rules v2 --cheaters 0.1 --cheat-mode evolve"], ["v2_cheat_evolve_seed3", 100, "--seed 3 --rules v2 --cheaters 0.1 --cheat-mode evolve"], ["v2_planted_honest_seed0", 100, "--seed 0 --rules v2 --cheaters 0.1 --cheat-mode planted_honest"], ["v2_planted_honest_seed1", 100, "--seed 1 --rules v2 --cheaters 0.1 --cheat-mode planted_honest"], ["v2_planted_honest_seed2", 100, "--seed 2 --rules v2 --cheaters 0.1 --cheat-mode planted_honest"], ["v2_planted_honest_seed3", 100, "--seed 3 --rules v2 --cheaters 0.1 --cheat-mode planted_honest"], ["v2_planted_honest_seed4", 100, "--seed 4 --rules v2 --cheaters 0.1 --cheat-mode planted_honest"]]
os.makedirs("runs", exist_ok=True)
for prev in glob.glob("/kaggle/input/*/runs"):        # resume: previous output of this kernel attached as input
    for d in os.listdir(prev):
        if not os.path.exists("runs/" + d): shutil.copytree(os.path.join(prev, d), "runs/" + d) if os.path.isdir(os.path.join(prev, d)) else shutil.copy(os.path.join(prev, d), "runs/" + d)
def gen_of(n):
    try: return pickle.load(open(f"runs/{n}/ckpt.pkl", "rb"))["gen"]
    except Exception:
        try: return max(json.loads(l)["gen"] for l in open(f"runs/{n}/progress.jsonl"))
        except Exception: return 0
status = {}
for n, g, a in JOBS:
    if os.path.exists(f"runs/{n}/DONE"): status[n] = "done(prev)"; continue
    left = BUDGET_MIN - (time.time() - T0) / 60
    if left < 10: status[n] = f"not started, gen {gen_of(n)}"; continue
    os.makedirs(f"runs/{n}", exist_ok=True); t = time.time()
    cmd = [sys.executable, "run_box.py", "--minutes", str(round(left - 5, 1)), "--max-gen", str(g), "--workers", "4", "--batch", "1024", "--out", f"runs/{n}"] + shlex.split(a)
    with open(f"runs/{n}.log", "a") as lf: r = subprocess.run(cmd, stdout=lf, stderr=subprocess.STDOUT)
    k = gen_of(n)
    if k >= g: open(f"runs/{n}/DONE", "w").close()
    status[n] = f"gen {k}/{g} rc {r.returncode} {(time.time() - t) / 60:.1f} min"
    print(n, status[n], flush=True)
    json.dump(dict(status=status, elapsed_min=round((time.time() - T0) / 60, 1)), open("runs/STATUS.json", "w"), indent=1)
json.dump(dict(status=status, elapsed_min=round((time.time() - T0) / 60, 1)), open("runs/STATUS.json", "w"), indent=1)
for f in ("genesis", "run_box.py"): shutil.rmtree(f, ignore_errors=True) if os.path.isdir(f) else os.remove(f)
print("ALL", status)
